#!/bin/sh
# Builds tests/oracle/svg_text_oracle.cpp against the kicad-cli link libraries of the
# reference build (SVG_plotter.cpp, PS_plotter.cpp, plotter.cpp live in common/libcommon.a, the
# stroke font in libkigal, see rust/docs/ORACLE.md) and, with "regen" as second argument,
# regenerates tests/golden/svg_text.txt (replayed by tests/test_svg_text_oracle.rs).
#
#   tests/oracle/build_svg_text_oracle.sh [outdir] [regen]
#
# The plot scripts are generated by the Rust test; regen first runs (from <kicad>/rust)
#   KICAD_PLOT_WRITE_SCRIPTS=1 cargo test -p kicad-plot --test test_svg_text_oracle
# which writes <kicad>/rust/target/plot-oracle/svg_text_scripts.txt.
#
# Debugging: <outdir>/svg_text_oracle <scripts> full   prints every produced file.
set -eu

HERE=$(cd "$(dirname "$0")" && pwd)
KICAD=$(cd "$HERE/../../../../.." && pwd)
OUT=${1:-$KICAD/rust/target/plot-oracle}
OUT=${OUT:-$KICAD/rust/target/plot-oracle}
BUILD=${KICAD_ORACLE_BUILD:-/home/user/kicad-oracle/build}
GOLDEN=$HERE/../golden

mkdir -p "$OUT"

INC="-I$BUILD -I$BUILD/common -I$KICAD/include -I$KICAD/libs/core/include -I$KICAD/libs/kimath/include \
     -I$KICAD/thirdparty/nlohmann_json -I$KICAD/thirdparty/fmt/include -I$KICAD/thirdparty/clipper2/Clipper2Lib/include -I$KICAD/thirdparty/dynamic_bitset \
     -I/usr/include/freetype2 -I/usr/include/harfbuzz"

# Link against everything kicad-cli links (libcommon.a pulls in much of the tree).
LIBS=$(cd "$BUILD" && grep -A3 "^build kicad/kicad-cli:" build.ninja | grep LINK_LIBRARIES | sed 's/^ *LINK_LIBRARIES = //')

# shellcheck disable=SC2086
(cd "$BUILD" && ${CXX:-c++} -std=c++20 -O1 -w -DNDEBUG $(wx-config --cxxflags core,base) $INC \
    -o "$OUT/svg_text_oracle" "$HERE/svg_text_oracle.cpp" -Wl,--start-group $LIBS -Wl,--end-group)

echo "built $OUT/svg_text_oracle"

if [ "${2:-}" = "regen" ]; then
    (cd "$KICAD/rust" && KICAD_PLOT_WRITE_SCRIPTS=1 cargo test -q -p kicad-plot --test test_svg_text_oracle >/dev/null 2>&1 || true)
    "$OUT/svg_text_oracle" "$KICAD/rust/target/plot-oracle/svg_text_scripts.txt" 2>/dev/null > "$GOLDEN/svg_text.txt"
    echo "regenerated $GOLDEN/svg_text.txt"
fi
